layers.vertex:
attribute vec3 aO, aE; attribute float aT; uniform float uTime; varying vec2 vP; varying float vU; vec3 arcAt(vec3 a, vec3 b, float f){ return mix(a, b, f); }
    void main(){
      float u = uTime - aT - 0.10, L = length(aE - aO), tt = L/18.0;
      if (u < 0. || u > tt){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec4 mv = viewMatrix*vec4(arcAt(aO, aE, u/tt), 1.); float S = .32;
      float c = cos(u*6.), s = sin(u*6.); vec2 q = mat2(c, -s, s, c)*position.xy;       // corona churns
      mv.xy += q*S*1.2; vP = position.xy; vU = u; gl_Position = projectionMatrix*mv;
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU;
    void main(){                                              // astral star: 4 long points + 4 short, bright core, soft halo
      vec2 p = vP; float r = length(p), a = atan(p.y, p.x);
      float d = abs(p.x)*2.2 + abs(p.y)*.9 - .55;                             // tall sharp crystal
      float edge = exp(-pow(d/.05, 2.)), fill = smoothstep(.04, -.12, d)*.35, facet = exp(-pow(p.x/.025, 2.))*smoothstep(.1, -.3, d)*.6;
      float halo = exp(-r*r*7.)*.18;
      vec3 o = (uOrange*(edge*.9 + fill + halo) + mix(uGold, vec3(1.), .5)*(facet + edge*.3))*smoothstep(1., .85, r);
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); }

layers.vertex:
attribute vec3 aO, aE; attribute float aT; uniform float uTime; varying float vS, vY, vF; vec3 arcAt(vec3 a, vec3 b, float f){ return mix(a, b, f); }
    void main(){
      float u = uTime - aT - 0.10, L = length(aE - aO), tt = L/18.0;
      if (u < 0. || u > tt + .2){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec3 d = (aE - aO)/L;
      float head = min(u*18.0, L), tail = max(0., head - .7) + max(0., u - tt)/.2*1.7;   // after the hit, the tail catches up
      if (head - tail < .01){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float s = position.x*.5 + .5;
      float fa = mix(tail, head, s)/L;
      vec3 P = arcAt(aO, aE, fa), T = normalize(arcAt(aO, aE, min(fa + .01, 1.)) - arcAt(aO, aE, max(fa - .01, 0.)));
      vec3 side = normalize(cross(T, P - cameraPosition));
      vS = s; vY = position.y; vF = 1. - clamp((u - tt)/.2, 0., 1.);
      gl_Position = projectionMatrix*viewMatrix*vec4(P + side*position.y*(.02 + .09*s), 1.);
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying float vS, vY, vF;
    void main(){ float a = pow(vS, 1.6)*exp(-vY*vY*5.), c = pow(vS, 3.)*exp(-vY*vY*30.);
      vec3 o = (mix(uOrange, uGold, .6)*a*.55 + vec3(1., .95, .85)*c*.35)*vF;
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); }

layers.vertex:
attribute vec3 aO; attribute vec4 aS, aD; attribute float aT; attribute vec2 aX; uniform float uTime; varying vec3 vN, vV, vW, vL; varying float vSeed, vCrack, vTopY, vRnd;
    void main(){
      float u = uTime - aT - aD.x; if (u < 0. || u > 3.00 + .5){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float du = aX.x > 0. ? uTime - aX.x : -1.; if (du > .16){ gl_Position = vec4(2.,2.,2.,1.); return; }          // destroyed: block collapses in 0.16 s (shards take over)
      float br = du > 0. ? 1. - du/.16 : 1.;
      float k = clamp(u/.25, 0., 1.), c1 = 1.9, rise = max(.02, 1. + (c1 + 1.)*pow(k - 1., 3.) + c1*pow(k - 1., 2.));   // ease-out-back
      float sink = smoothstep(3.00, 3.00 + .45, u);
      vec3 hs = vec3(aS.x, aS.y*rise*br, aS.x*mix(.85, 1., aD.w))*.5;
      float r = min(min(hs.x, hs.z), hs.y)*aD.w*(aD.w > .6 ? 1. : .45);   // blocks: only slightly softened edges
      vec3 q = position*2.*hs, c = clamp(q, -hs + r, hs - r), d = q - c; float L = length(d);
      vec3 nn = L > 1e-5 ? d/L : vec3(0., 1., 0.);
      q = c + nn*r;
      float top = smoothstep(.3, .9, nn.y);                                     // chipped, slightly uneven top
      q.y += top*(fract(sin(dot(floor(q.xz*6.), vec2(12.9, 78.2)) + aD.z*40.)*4375.5) - .5)*.05*hs.x*2.;
      vL = q/(2.*hs); vTopY = hs.y*2.;
      q.y += hs.y - (aD.w > .6 ? hs.y*.6 : 0.);                                  // blocks stand on the ground; rubble half buried
      float cy = cos(aS.z), sy = sin(aS.z); vec3 p = vec3(cy*q.x - sy*q.z, q.y, sy*q.x + cy*q.z); vec3 n = vec3(cy*nn.x - sy*nn.z, nn.y, sy*nn.x + cy*nn.z);
      float ct = cos(aS.w), st = sin(aS.w), td = aD.y; vec3 ax = vec3(cos(td), 0., sin(td));   // a slight lean
      p = p*ct + cross(ax, p)*st + ax*dot(ax, p)*(1. - ct); n = n*ct + cross(ax, n)*st + ax*dot(ax, n)*(1. - ct);
      vec3 W = aO + p - vec3(0., sink*(hs.y*2.)*1.05, 0.);
      vN = n; vV = normalize(cameraPosition - W); vW = W; vSeed = aD.z; vCrack = aX.y; vRnd = aD.w;
      gl_Position = projectionMatrix*viewMatrix*vec4(W, 1.);
    }

layers.fragment:
uniform vec3 uMoon; uniform float uTime; varying vec3 vN, vV, vW, vL; varying float vSeed, vCrack, vTopY, vRnd;
    float h2(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7)))*43758.5453); }
    float vn(vec2 p){ vec2 i = floor(p), f = fract(p); f = f*f*(3. - 2.*f);
      return mix(mix(h2(i), h2(i + vec2(1., 0.)), f.x), mix(h2(i + vec2(0., 1.)), h2(i + vec2(1., 1.)), f.x), f.y); }
    void main(){
      vec3 n = normalize(vN), V = normalize(vV);
      float h = clamp(vL.y + .5, 0., 1.), nv = clamp(dot(n, V), 0., 1.), l = max(dot(n, uMoon), 0.);
      float topF = smoothstep(.55, .92, n.y), bevel = smoothstep(.12, .45, n.y)*(1. - smoothstep(.62, .9, n.y));
      float side = dot(vL.xz, vec2(.7, -.7))*4. + vL.x*3.;                       // vertical chipped facets on the sides
      float band = vn(vec2(side*.75 + vSeed*13., vL.y*.25));
      vec3 deep = vec3(.03, .12, .3), mid = vec3(.12, .34, .6), pale = vec3(.36, .58, .78);   // natural ice: desaturated, lighter upwards
      vec3 col = mix(deep, mid, smoothstep(0., 1., h*.8 + .15));
      col *= .88 + .2*smoothstep(.4, .6, band);                                  // a few wide facets, subtle
      col = mix(col, pale, topF*.7*(vRnd > .6 ? .5 : 1.));
      col += vec3(.2, .4, .6)*pow(1. - nv, 3.)*.18;                             // soft cool rim
      col *= .7 + .4*l;
      if (vCrack > .5){                                                            // damage stages: bright jagged cracks
        float g = h*5.5 + vSeed*17. + side*1.3, g2 = h*9. - vSeed*11. + side*2.;
        float cr = pow(1. - abs(fract(g + .15*vn(vL.xy*9.)) - .5)*2., 30.) + (vCrack > 1.5 ? pow(1. - abs(fract(g2 + .2*vn(vL.zy*11.)) - .5)*2., 26.) : 0.);
        col = mix(col, vec3(.5, .66, .8), clamp(cr*(vCrack > 1.5 ? .5 : .28), 0., 1.));
      }
      col *= smoothstep(-.05, .1, h)*.25 + .75;                                  // a little darker at the foot
      gl_FragColor = vec4(col*1.12, 1.);
    }

layers.vertex:
attribute vec3 aO;attribute float aT;uniform float uTime;varying vec2 vP;varying float vU;
void main(){vU=uTime-aT;if(vU<0.||vU>3.6){gl_Position=vec4(2.,2.,2.,1.);return;}vP=position.xy*2.8;
gl_Position=projectionMatrix*viewMatrix*vec4(aO+vec3(vP.x,.028,-vP.y),1.);}

layers.fragment:
uniform vec3 uOrange,uGold;varying vec2 vP;varying float vU;
void main(){float r=length(vP),R=2.4,f=smoothstep(0.,.18,vU)*(1.-smoothstep(3.,3.55,vU));
float line=exp(-pow((r-R)/.025,2.)),wash=smoothstep(R,R-.18,r)*.018;
vec3 o=(uOrange*(line*.55+wash)+uGold*exp(-pow((r-R)/.009,2.))*.16)*f*smoothstep(2.8,2.6,r);
gl_FragColor=vec4(o,1.);}
